package com.library.util;
import com.library.exception.LibraryException; import java.time.Year; import java.util.regex.Pattern;
public final class ValidationUtil { private static final Pattern EMAIL=Pattern.compile("^[A-Za-z0-9+_.-]+@[A-Za-z0-9.-]+$"); private static final Pattern ISBN=Pattern.compile("^[0-9Xx-]{10,17}$"); private static final Pattern PHONE=Pattern.compile("^[0-9]{10}$"); private ValidationUtil(){} public static String required(String value,String label){if(value==null||value.trim().isEmpty())throw new LibraryException(label+" is required.");return value.trim();} public static void email(String v){if(!EMAIL.matcher(required(v,"Email")).matches())throw new LibraryException("Enter a valid email address.");} public static void studentEmail(String v){email(v);if(!v.trim().toLowerCase().endsWith("@gnu.ac.in"))throw new LibraryException("Student email must end with @gnu.ac.in.");} public static void phone(String v){if(!PHONE.matcher(required(v,"Phone number")).matches())throw new LibraryException("Phone number must contain exactly 10 digits.");} public static void enrollment(long v){if(v<10_000_000_000L||v>99_999_999_999L)throw new LibraryException("Enrollment number must contain exactly 11 digits.");} public static void password(String v){if(v==null||v.length()<6)throw new LibraryException("Password must contain at least 6 characters.");} public static void isbn(String v){if(!ISBN.matcher(required(v,"ISBN")).matches())throw new LibraryException("Enter a valid ISBN (10 or 13 digits, optionally with hyphens).");} public static void year(int v){if(v<1000||v>Year.now().getValue()+1)throw new LibraryException("Enter a reasonable publication year.");} public static void quantity(int v){if(v<0)throw new LibraryException("Quantity cannot be negative.");} public static void semester(int v){if(v<1||v>12)throw new LibraryException("Semester must be between 1 and 12.");} }
